  "properties": {
    "schemaVersion": {
      "const": "2.0.0"
    },
    "id": {
      "type": "string",
      "pattern": "^TASK-[0-9]{4,}$"
    },
    "round_id": {
      "type": "string",
      "pattern": "^R-[0-9]{4}$",
      "description": "The sole active governed round that owns this task. Runtime matching and active-round validation are mandatory before resource acquisition."
    },
    "status": {
      "enum": [
        "queued",
        "ready",
        "lock_denied",
        "in_progress",
        "checkpoint",
        "pre_merge",
        "merging",
        "completed",
        "awaiting_human_review",
        "experimental_blocked",
        "escalated",
        "rgr_pending",
        "cancelled"
      ]
    },
    "discipline": {
      "enum": ["owner", "architect", "inspector", "engineer", "auditor"],
      "description": "The governance authority source. Executor kind, runtime, model, effort, skill, and capabilities cannot change this value or its path/effect authority."
    },
    "discipline_specialization": {
      "type": "string",
      "minLength": 1
    },
    "title": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200
    },
    "description": {
      "type": "string"
    },
    "lifecycle": {
      "enum": ["supported", "experimental"],
      "default": "supported"
    },
    "acceptance_commands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/argv"
      },
      "description": "Literal shell-free argv arrays for task-specific acceptance."
    },
    "coupled_task_group": {
      "type": ["string", "null"],
      "pattern": "^CTG-[0-9]{4,}$"
    },
    "coupled_pipeline_position": {
      "type": ["string", "null"],
      "enum": [null, "architect", "inspector", "engineer"]
    },
    "upstream_task_id": {
      "type": ["string", "null"],
      "pattern": "^TASK-[0-9]{4,}$"
    },
    "target_substrates": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "enum": ["F1", "F2", "F3", "F4", "F5"]
      }
    },
    "target_modules": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "pattern": "^MOD-"
      },
      "description": "Module resource-lock keys. Empty is permitted only when the task has no module target."
    },
    "target_invariants": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "pattern": "^INV-"
      }
    },
    "db_isolation": {
      "enum": ["database", "cluster"]
    },
    "iteration_count": {
      "type": "integer",
      "minimum": 0
    },
    "max_iterations": {
      "type": "integer",
      "minimum": 1
    },
    "created_at": {
      "type": "string",
      "format": "date-time"
    },
    "spawned_at": {
      "type": ["string", "null"],
      "format": "date-time"
    },
    "completed_at": {
      "type": ["string", "null"],
      "format": "date-time"
    },
    "branch": {
      "type": ["string", "null"]
    },
    "worktree_id": {
      "type": ["string", "null"],
      "pattern": "^WT-"
    },
    "prompt_composition_id": {
      "type": ["string", "null"],
      "pattern": "^PC-[a-f0-9]{16}$"
    },
    "executor": {
      "description": "Immutable requested executor contract. Resolution is recorded only in task-execution evidence.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "kind": {},
        "action_id": {},
        "argv": {},
        "cwd": {},
        "inputs": {},
        "outputs": {},
        "effects": {},
        "timeout_ms": {},
        "authority_checks": {},
        "runtime": {},
        "model": {},
        "effort": {},
